"""Product-team briefs generated by a model; facts and readiness stay deterministic."""
from collections import Counter
import datetime as dt
import json
from .ports import ModelRequest


def compact_cross_checks(value):
    """Bound transport/model evidence; full intervals remain in saved evidence."""
    result={k:v for k,v in value.items() if k not in ('history_qualification','shop_history_qualification','examples')}
    result['examples']=[{**row,'shop_sales_intervals':row.get('shop_sales_intervals',[])[-3:],
        'listing_engagement_intervals':{k:v[-3:] for k,v in row.get('listing_engagement_intervals',{}).items()}} for row in value.get('examples',[])[:3]]
    result['interval_scope']='Most recent three intervals for at most three examples; full history remains in evidence.json'
    return result

def cross_checks(dataset, candidate):
    identities=set(candidate['listing_ids']);sellers={r['seller_id'] for r in dataset['records'] if r['id'] in identities}
    related=dataset['metadata'].get('history',{}).get('related_observations',[])
    listing_series={};shop_series={}
    for record in dataset['records']:
        if record['id'] in identities:
            listing_series.setdefault(record['id'],[]).append({'observed_at':record['observed_at'],'metrics':record['metrics'],'source_run_id':dataset['metadata'].get('source_run_id')})
    observations=[{'run_id':dataset['metadata'].get('source_run_id'),'shops':dataset['metadata'].get('shops',[]),'listings':[]}]+related
    for observation in observations:
        for row in observation.get('listings',[]):
            if row['id'] in identities:listing_series.setdefault(row['id'],[]).append({'observed_at':row['observed_at'],'metrics':row['metrics'],'source_run_id':observation['run_id']})
        for row in observation.get('shops',[]):
            if str(row['shop_id']) in sellers:shop_series.setdefault(str(row['shop_id']),[]).append({**row,'source_run_id':observation['run_id']})
    def intervals(series, metric):
        values={}
        for row in series:
            raw=row.get(metric) if metric=='transaction_sold_count' else next((m['value'] for m in row.get('metrics',[]) if m.get('scope')=='listing' and m.get('name')==metric),None)
            if type(raw) not in (int,float) or not row.get('observed_at'):continue
            instant=dt.datetime.fromisoformat(row['observed_at'].replace('Z','+00:00'))
            if instant.tzinfo is None:continue
            values[instant]=(raw,row['source_run_id'])
        ordered=sorted(values.items());result=[]
        for (a,av),(b,bv) in zip(ordered,ordered[1:]):
            days=(b-a).total_seconds()/86400
            result.append({'from':a.isoformat(),'to':b.isoformat(),'days':days,'before':av[0],'after':bv[0],
                'change':bv[0]-av[0],'per_day':(bv[0]-av[0])/days if days>=1 and bv[0]>=av[0] else None,
                'reset_or_correction':bv[0]<av[0],'source_run_ids':[av[1],bv[1]]})
        return result
    checked=[]
    rows={r['id']:r for r in dataset['records']}
    for identity,series in listing_series.items():
        row=rows[identity];shop=shop_series.get(row['seller_id'],[])
        shop_rows=[r for r in dataset['records'] if r['seller_id']==row['seller_id']]
        profile={'saved_listing_count':len(shop_rows),'category_counts':dict(Counter(r['category'] or 'unknown' for r in shop_rows)),
            'candidate_listing_count':sum(r['id'] in identities for r in shop_rows),
            'scope':'Listings present in this saved query only; not full shop inventory or sales mix'}
        changes={name:intervals(series,name) for name in ('views','favorites')}
        latest=max(shop,key=lambda s:s.get('observed_at') or '') if shop else None
        sales=intervals(shop,'transaction_sold_count')
        if any(changes.values()) or latest:
            checked.append({'listing_id':identity,'shop_id':row['seller_id'],'listing_engagement_intervals':changes,
                'shop_latest':{k:latest.get(k) for k in ('transaction_sold_count','listing_active_count','review_count','review_average','observed_at','source_run_id')} if latest else None,
                'shop_saved_category_profile':profile,'shop_sales_intervals':sales,'listing_sales':None,'listing_purchase_demand':'unverified',
                'shop_scope':'Entire shop; not attributable to this listing, category or niche'})
    checked.sort(key=lambda x:(-int(any(x['listing_engagement_intervals'].values())),x['listing_id']))
    return {'matched_shops':len(shop_series),'matched_listings_with_history_or_shop':len(checked),'examples':checked[:8],
        'shop_history_qualification': {seller: dataset['metadata'].get('history',{}).get('shop_series',{}).get(seller, {'trend_status':'insufficient_evidence'}) for seller in sellers},
        'history_qualification': {identity: dataset['metadata'].get('history',{}).get('listing_series',{}).get(identity, {'trend_status':'insufficient_evidence'}) for identity in identities},
        'positive_engagement_intervals':sum(d['change']>0 and d['days']>=1 for x in checked for intervals_ in x['listing_engagement_intervals'].values() for d in intervals_),
        'positive_shop_sales_intervals':sum(d['change']>0 and d['days']>=1 for series in shop_series.values() for d in intervals(series,'transaction_sold_count')),
        'demand_status':'unverified','listing_purchase_demand':None,
        'scope':'Identity-matched repeated observations; listing engagement and whole-shop performance remain separate. Short windows, seasonality and exposure confound demand.'}

def request(base):
    schema=json.loads(json.dumps(base.schema));item=schema['properties']['items']['items'];refs=item['properties']['evidence_ids']['items']
    statement={'type':'object','additionalProperties':False,'required':['text','basis','evidence_ids'],'properties':{
        'text':{'type':'string'},'basis':{'type':'string','enum':['observed','design_hypothesis']},
        'evidence_ids':{'type':'array','minItems':1,'maxItems':3,'items':refs}}}
    fields={'product_concept':{'type':'string'},'intended_customer':statement,'customer_job':statement,
        'deliverables':{'type':'array','minItems':1,'maxItems':5,'items':statement},
        'differentiation':statement,'acceptance_checks':{'type':'array','minItems':1,'maxItems':5,'items':{'type':'string'}},
        'validation_plan':{'type':'array','minItems':1,'maxItems':5,'items':{'type':'string'}},
        'risks':{'type':'array','minItems':1,'maxItems':5,'items':{'type':'string'}}}
    item['properties']['product_brief']={'type':'object','additionalProperties':False,'required':list(fields),'properties':fields}
    item['required'].append('product_brief');schema['properties']['items']['maxItems']=3
    context=json.loads(base.prompt)
    context['assignment']='Generate a concrete product-team handoff for a validation experiment, not a verified launch decision.'
    system=base.system+' Select at most two focused product concepts. For each, generate the product_brief: a concrete audience, customer job, digital deliverables and formats, meaningful differentiation, testable acceptance checks, validation plan and risks. Label proposed choices design_hypothesis; observed claims need supporting excerpt citations. Do not copy designs, use trademarks, or infer unmet needs from missing examples. Cross-examine linked shop counters and repeated listing engagement; a successful shop never proves demand for the chosen listing. Never call a product launch-ready. Acknowledge cheap-product crowding when benchmark shares are high. Images are interpreted locally; local image notes are unverified. Do not invent image observations, file dimensions or content absent in evidence. Proposed dimensions/counts may be design_hypothesis only. Output concise, useful briefs.'
    return ModelRequest(system,json.dumps(context,ensure_ascii=False,separators=(',',':')),schema)

def validate(value,candidates,maximum=5):
    from .research import grounded_prose,validate_selection
    core={**value,'items':[{k:v for k,v in item.items() if k!='product_brief'} for item in value.get('items',[])]}
    validate_selection(json.dumps(core),candidates,maximum=maximum)
    by_id={c['candidate_id']:c for c in candidates};briefs={}
    fields={'product_concept','intended_customer','customer_job','deliverables','differentiation','acceptance_checks','validation_plan','risks'}
    def string(v):
        if not isinstance(v,str) or not v.strip() or len(v)>1200:raise ValueError('Invalid brief text')
        # Numerical proposals are allowed; unsupported commercial assertions are not.
        import re
        grounded_prose(re.sub(r'\d+(?:[.,]\d+)?','',v))
    for item in value['items']:
        brief=item.get('product_brief');cid=item['candidate_id']
        if not isinstance(brief,dict) or set(brief)!=fields:raise ValueError('Invalid product brief')
        refs={e['evidence_id'] for e in by_id[cid]['evidence']}
        string(brief['product_concept'])
        statements=[brief['intended_customer'],brief['customer_job'],brief['differentiation']]
        if not isinstance(brief['deliverables'],list) or not 1<=len(brief['deliverables'])<=5:raise ValueError('Invalid deliverables')
        statements+=brief['deliverables']
        for statement in statements:
            if not isinstance(statement,dict) or set(statement)!={'text','basis','evidence_ids'} or statement['basis'] not in ('observed','design_hypothesis'):raise ValueError('Invalid brief statement')
            string(statement['text'])
            if statement['basis']=='observed':grounded_prose(statement['text'])
            ids=statement['evidence_ids']
            if not isinstance(ids,list) or not 1<=len(ids)<=3 or any(r not in refs for r in ids) or len(set(ids))!=len(ids):raise ValueError('Invalid brief citation')
        for field in ('acceptance_checks','validation_plan','risks'):
            if not isinstance(brief[field],list) or not 1<=len(brief[field])<=5:raise ValueError('Invalid brief checklist')
            for v in brief[field]:string(v)
        briefs[cid]={**brief,'launch_readiness':'validation_required','purchase_demand_verified':False}
    return core,briefs
